81	    /** Add a claim for a person; a missing date takes the sheet's today, a missing note is empty. Refused
82	     *  when its date is inside a closed period, or when it is a correction that does not name a SETTLED claim of
83	     *  the person. */
84	    @Transactional
85	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
86	            String corrects) {
87	        sheets.load(sheetId, user);
88	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
89	        LocalDate today = sheet.getToday();
90	        Person person = people.findByIdAndSheetId(personId, sheetId)
91	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
92	        refuseIfClosed(sheetId, date != null ? date : today);
93	        refuseIfRetired(person, date != null ? date : today);
94	        refuseUnlessCorrects(sheetId, personId, amount, corrects);
95	        Rollup.Figures before = rollup.of(sheetId);
96	        LocalDate claimDate = date != null ? date : today;
97	        LocalDate dueBy = claimDate.plusDays(sheet.termsFor(person.gradeOn(claimDate), claimDate));
98	        Claim added = claims.saveAndFlush(new Claim(sheetId, personId, scaled(amount), claimDate, dueBy,
99	                noteOf(note), corrects, claims.lastListed(sheetId) + 1));
100	        added.logStatus(user, today, shownDue(sheet, added, person));
101	        audit.recordOnCommit(entry("CLAIM_ADDED", user, person, added, added.getNumber()));
102	        rollup.recordChanges(sheetId, user, before);
103	        return added;
104	    }
