200	    /** Defer an OPEN claim until a day after the sheet's today: until the sheet's today reaches that day it counts
201	     *  in no total, is not overdue, cannot be settled and is left unbound by a statement. Refused for a claim that
202	     *  is not OPEN, a day not after today and a claim dated inside a closed period. */
203	    @Transactional
204	    public Claim defer(String sheetId, String user, long id, LocalDate until) {
205	        sheets.load(sheetId, user);
206	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
207	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
208	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
209	        refuseIfClosed(sheetId, claim.getDate());
210	        if (claim.getStatus() != ClaimStatus.OPEN) {
211	            throw new ResponseStatusException(HttpStatus.CONFLICT,
212	                    "A " + claim.getStatus() + " claim cannot be deferred; only an OPEN one can");
213	        }
214	        if (!until.isAfter(sheet.getToday())) {
215	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A claim is deferred to a day after today");
216	        }
217	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
218	        Rollup.Figures before = rollup.of(sheetId);
219	        claim.setDeferredUntil(until);
220	        Claim deferred = claims.saveAndFlush(claim);
221	        audit.recordOnCommit(entry("CLAIM_DEFERRED", user, person, deferred, deferred.getNumber()) + " until=" + until);
222	        rollup.recordChanges(sheetId, user, before);
223	        return deferred;
224	    }
