226	    /** A steward approves a PENDING claim: it becomes SETTLED, its due fixed as it is at this moment (its live
227	     *  figure with the late charge it has gained). Refused for a clerk, for the user who opened the claim, for a
228	     *  claim that is not PENDING and for one dated inside a closed period. */
229	    @Transactional
230	    public Claim approve(String sheetId, String user, long id) {
231	        sheets.load(sheetId, user);
232	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
233	        Claim claim = pendingClaim(sheetId, user, id);
234	        if (user.equals(claim.getOpenedBy())) {
235	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot approve it");
236	        }
237	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
238	        BigDecimal due = dueNow(sheet, claim, person);
239	        Rollup.Figures before = rollup.of(sheetId);
240	        claim.setStatus(ClaimStatus.SETTLED);
241	        claim.setSettledDue(due);
242	        claim.logStatus(user, sheet.getToday(), shownDue(sheet, claim, person));
243	        Claim changed = claims.saveAndFlush(claim);
244	        audit.recordOnCommit(entry("CLAIM_APPROVED", user, person, changed, changed.getNumber())
245	                + " due=" + dueText(changed));
246	        rollup.recordChanges(sheetId, user, before);
247	        return changed;
248	    }
