250	    /** A steward rejects a PENDING claim with a reason: it is OPEN again, bound again by its person's last
251	     *  statement if that statement included it. Refused for a clerk, for a claim that is not PENDING and for one
252	     *  dated inside a closed period. */
253	    @Transactional
254	    public Claim reject(String sheetId, String user, long id, String reason) {
255	        sheets.load(sheetId, user);
256	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
257	        Claim claim = pendingClaim(sheetId, user, id);
258	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
259	        Rollup.Figures before = rollup.of(sheetId);
260	        claim.setStatus(ClaimStatus.OPEN);
261	        claim.logStatus(user, sheet.getToday(), shownDue(sheet, claim, person));
262	        Claim changed = claims.saveAndFlush(claim);
263	        audit.recordOnCommit(entry("CLAIM_REJECTED", user, person, changed, changed.getNumber())
264	                + " reason=" + reason.trim());
265	        rollup.recordChanges(sheetId, user, before);
266	        return changed;
267	    }
