301	    /** A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number and date,
302	     *  loses any figure a statement bound it to (it is live again until its new person's next statement), and is
303	     *  listed as its new person's newest claim. Refused for a clerk, for a SETTLED or VOID claim, for a move to the
304	     *  person it is already of, for one dated inside a closed period or after the new person retired, and for a
305	     *  correction the new person has no SETTLED claim of that number for. */
306	    @Transactional
307	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
308	        sheets.load(sheetId, user);
309	        sheetStore.findLockedById(sheetId).orElseThrow();
310	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
311	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
312	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
313	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
314	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
315	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward reassigns a claim");
316	        }
317	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
318	            throw new ResponseStatusException(HttpStatus.CONFLICT,
319	                    "A " + claim.getStatus() + " claim cannot be reassigned");
320	        }
321	        if (claim.getPersonId().equals(to.getId())) {
322	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is already " + to.getName() + "'s");
323	        }
324	        refuseIfClosed(sheetId, claim.getDate());
325	        refuseIfRetired(to, claim.getDate());
326	        refuseUnlessCorrects(sheetId, to.getId(), claim.getAmount(), claim.getCorrects());
327	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
328	        Rollup.Figures before = rollup.of(sheetId);
329	        claim.unbind();
330	        claim.reassign(to.getId(), claims.lastListed(sheetId) + 1);
331	        Claim moved = claims.saveAndFlush(claim);
332	        audit.recordOnCommit(entry("CLAIM_REASSIGNED", user, to, moved, moved.getNumber())
333	                + " from=" + from.getName() + " to=" + to.getName());
334	        rollup.recordChanges(sheetId, user, before);
335	        return moved;
336	    }
