338	    /** The PENDING claim a steward approves or rejects; refused for a clerk, a claim in any other status and one
339	     *  dated inside a closed period. */
340	    private Claim pendingClaim(String sheetId, String user, long id) {
341	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
342	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
343	        refuseIfClosed(sheetId, claim.getDate());
344	        if (claim.getStatus() != ClaimStatus.PENDING) {
345	            throw new ResponseStatusException(HttpStatus.CONFLICT,
346	                    "A " + claim.getStatus() + " claim is not waiting for approval");
347	        }
348	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
349	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward approves or rejects a claim");
350	        }
351	        return claim;
352	    }
