426	    /** Refuse a change to a claim dated inside a closed period of the sheet. */
427	    private void refuseIfClosed(String sheetId, LocalDate date) {
428	        if (periods.existsBySheetIdAndClosedTrueAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, date, date)) {
429	            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim's date is inside a closed period");
430	        }
431	    }
