441	    /** An audit line about a claim; one with a number (a void claim keeps the one it had) ends with it. */
442	    private static String entry(String event, String user, Person person, Claim claim, String number) {
443	        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
444	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
445	                + (number == null ? "" : " number=" + number);
446	    }
447	
448	    /** The due on an amount at a rate (a percent): amount × rate / 100, rounded to the cent as the claim it is on
449	     *  rounds (half up rounds a negative half away from zero, as its opposite would). */
450	    public static BigDecimal dueOn(BigDecimal amount, BigDecimal rate, RoundingMode rounding) {
451	        return amount.multiply(rate).movePointLeft(2).setScale(2, rounding);
452	    }
453	
454	    /** The date that decides how a claim's live figures round: its own date, or for a correction the date of the
455	     *  claim of the same person it corrects. */
456	    public static LocalDate roundingDate(Claim claim, Collection<Claim> sheetClaims) {
457	        if (claim.getCorrects() == null) {
458	            return claim.getDate();
459	        }
460	        return sheetClaims.stream()
461	                .filter(c -> c.getPersonId().equals(claim.getPersonId()) && claim.getCorrects().equals(c.getNumber()))
462	                .map(Claim::getDate).findFirst().orElse(claim.getDate());
463	    }
464	
465	    /** The late charge an OPEN or PENDING claim, not deferred, has gained on its figure by the sheet's today: the late percent in force on its date of
466	     *  the figure for every full 30 days past the day it is due by, rounded as the claim rounds; 0.00 when not overdue,
467	     *  it has no figure, or it is a correction. */
468	    public static BigDecimal lateCharge(Claim claim, BigDecimal figure, Sheet sheet) {
469	        BigDecimal none = BigDecimal.ZERO.setScale(2);
470	        if (!claim.getStatus().isOpen() || claim.isDeferredOn(sheet.getToday())) {
471	            return none;
472	        }
473	        return lateChargeAsOpen(claim, figure, sheet);
474	    }
475	
476	    /** The late charge a claim would have gained on its figure by the sheet's today were it still open. */
477	    private static BigDecimal lateChargeAsOpen(Claim claim, BigDecimal figure, Sheet sheet) {
478	        BigDecimal none = BigDecimal.ZERO.setScale(2);
479	        if (figure == null || claim.isCorrection()) {
480	            return none;
481	        }
482	        long periods = ChronoUnit.DAYS.between(claim.getDueBy(), sheet.getToday()) / 30;
483	        return periods <= 0 ? none : dueOn(figure, sheet.latePctOn(claim.getDate()).multiply(BigDecimal.valueOf(periods)),
484	                sheet.roundingFor(claim.getDate()));
485	    }
486	
487	    /** A claim's live figure at a rate: its due on its amount, rounded as the claim rounds, raised to the floor
488	     *  (the one in force on its date) unless it is a correction. */
489	    public static BigDecimal liveFigure(Claim claim, BigDecimal rate, BigDecimal floor, RoundingMode rounding) {
490	        BigDecimal due = dueOn(claim.getAmount(), rate, rounding);
491	        return claim.isCorrection() ? due : floored(due, floor);
492	    }
493	
494	    /** A live due raised to the sheet's floor when it is below it. */
495	    public static BigDecimal floored(BigDecimal due, BigDecimal floor) {
496	        return floor != null && due.compareTo(floor) < 0 ? floor : due;
497	    }
498	
499	    private static BigDecimal scaled(BigDecimal amount) {
500	        return amount.setScale(2, RoundingMode.UNNECESSARY);
501	    }
502	
503	    private static String noteOf(String note) {
504	        return note == null ? "" : note.trim();
505	    }
