529	/** A claim a person on a sheet has made: an amount (two decimals), a date, a note and a status. A negative amount
530	 *  makes it a correction of the SETTLED claim of the same person whose number it names. */
531	@Entity
532	@Table(name = "claim")
533	public class Claim {
534	
535	    @Id
