596	    private long listed;
597	
598	    /** The claim's status log, oldest first: a line for each status it has had, the DRAFT it was added as first. */
599	    @ElementCollection(fetch = FetchType.EAGER)
600	    @CollectionTable(name = "claim_log", joinColumns = @JoinColumn(name = "claim_id"))
601	    @OrderColumn(name = "seq")
602	    @BatchSize(size = 100)
