755	    /** Whether the claim is deferred on this day: it is OPEN and deferred until a later day. While deferred it
756	     *  counts in no total, is not overdue, cannot be settled and is left unbound by a statement. */
757	    public boolean isDeferredOn(LocalDate today) {
758	        return status == ClaimStatus.OPEN && deferredUntil != null && today != null && today.isBefore(deferredUntil);
759	    }
