773	/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a DRAFT, OPEN or PENDING claim can be VOID. A clerk
774	 *  settling an OPEN claim above the clerk limit makes it PENDING, which a steward approves (SETTLED) or rejects
775	 *  (OPEN again). */
776	public enum ClaimStatus {
777	    DRAFT, OPEN, PENDING, SETTLED, VOID;
778	
779	    /** Whether a claim in this status may move to {@code next} by a status change; approving or rejecting a
780	     *  PENDING claim is not a status change. */
781	    public boolean canBecome(ClaimStatus next) {
782	        return switch (next) {
783	            case OPEN -> this == DRAFT;
784	            case SETTLED -> this == OPEN;
785	            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
786	            case DRAFT, PENDING -> false;
787	        };
788	    }
789	
790	    /** Whether a claim in this status counts toward what is claimed and due: OPEN, PENDING and SETTLED ones do. */
791	    public boolean counts() {
792	        return this == OPEN || this == PENDING || this == SETTLED;
793	    }
794	
795	    /** Whether a claim in this status is still open: OPEN or PENDING, so it goes overdue and gains the late charge. */
796	    public boolean isOpen() {
797	        return this == OPEN || this == PENDING;
798	    }
799	}
