217	export interface RateView {
218	  grade: Grade;
219	  /** The percent with exactly two decimals, e.g. "12.50". */
220	  rate: string;
221	  /** The day it takes effect (yyyy-mm-dd); null when it applies from the beginning of time. */
222	  from: string | null;
223	  /** The last day it applies (yyyy-mm-dd); null when it does not end. */
224	  to: string | null;
225	}
226	
227	/** The rate among a grade's rates (in the order they take effect) in force on a date (yyyy-mm-dd):
228	 *  the one with the latest from-date on or before it, unless the date is after its to-date; undefined
229	 *  when the date is before them all, or that rate has ended by then (an earlier one does not take over again). */
230	export function rateOn(gradeRates: readonly RateView[], date: string): string | undefined {
231	  let inForce: RateView | undefined;
232	  for (const r of gradeRates) if (r.from === null || r.from <= date) inForce = r;
233	  return inForce === undefined || (inForce.to !== null && inForce.to < date) ? undefined : inForce.rate;
234	}
235	
236	/** Rates in the order they take effect: the one with no from-date first, then by from-date. */
237	function byFrom(a: RateView, b: RateView): number {
238	  return a.from === b.from ? 0 : a.from === null ? -1 : b.from === null ? 1 : a.from < b.from ? -1 : 1;
239	}
240	
241	/** A rate the form accepts: a percent of 0.00 or more, up to 999.99, with up to two decimals. */
242	export const RATE_PATTERN = /^\d{1,3}(\.\d{1,2})?$/;
243	
244	/** The floor a sheet starts with. */
245	export const DEFAULT_FLOOR = '1.00';
246	
247	/** The due terms used before a sheet is loaded: its starting floor and no late charge. */
248	export const DEFAULT_DUE_TERMS: DueTerms = { today: '', policyDate: null, settings: [] };
249	
250	/** The late percent a sheet starts with. */
251	export const DEFAULT_LATE_PCT = '0.00';
252	
253	/** What is shown in place of a due when its grade has no rate. */
254	export const NOT_AVAILABLE = 'n/a';
255	
256	/** The due on an amount (in whole cents) at a rate (a percent, e.g. "12.50"), in whole cents:
257	 *  amount × rate / 100, rounded to the cent half to even, or half up when `halfUp` (a negative amount as its
258	 *  opposite is, negated). Exact, whatever the size of the amount. */
259	export function dueCents(amountCents: number, rate: string, halfUp = false): number {
260	  if (amountCents < 0) return -dueCents(-amountCents, rate, halfUp);
261	  const [whole, frac = ''] = rate.split('.');
262	  const basisPoints = BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0').slice(0, 2));
263	  const product = BigInt(amountCents) * basisPoints;
264	  const quotient = product / 10000n;
265	  const remainder = product % 10000n;
266	  const roundUp = remainder > 5000n || (remainder === 5000n && (halfUp || quotient % 2n === 1n));
267	  return Number(roundUp ? quotient + 1n : quotient);
268	}
269	
270	/** The sheet's settings a claim's due depends on: its dated floors and late percents, its policy date and, for
271	 *  the late charge, its today. */
272	export type DueTerms = Pick<SheetView, 'today' | 'policyDate' | 'settings'>;
273	
274	/** The floor in force on a claim's date (yyyy-mm-dd). */
275	export function floorOn(sheet: DueTerms, date: string): string {
276	  return settingOn(sheet.settings, 'floor', date, DEFAULT_FLOOR);
277	}
278	
279	/** The late percent in force on a claim's date (yyyy-mm-dd). */
280	export function latePctOn(sheet: DueTerms, date: string): string {
281	  return settingOn(sheet.settings, 'late-pct', date, DEFAULT_LATE_PCT);
282	}
283	
284	/** Whether a claim whose figures round by this date (yyyy-mm-dd) rounds half up: it is before the sheet's policy
285	 *  date (its today when it has none); on or after it, it rounds half to even. */
286	export function roundsHalfUp(date: string, sheet: DueTerms): boolean {
287	  return date < (sheet.policyDate ?? sheet.today);
288	}
289	
290	/** The late charge an OPEN or PENDING claim, not deferred, has gained on its figure (in whole cents) by the sheet's today: the
291	 *  late percent of the figure for every full 30 days past the day it is due by, rounded as the claim rounds.
292	 *  A correction (a negative amount) gains none. */
293	export function lateChargeCents(
294	  c: { amount: string; date: string; dueBy: string; status: ClaimStatus; deferredUntil: string | null },
295	  figureCents: number,
296	  sheet: DueTerms,
297	): number {
298	  if (cents(c.amount) < 0 || !isOverdue(c, sheet.today)) return 0;
299	  const days = (Date.parse(sheet.today) - Date.parse(c.dueBy)) / 86_400_000;
300	  const periods = Math.floor(days / 30);
301	  if (periods <= 0) return 0;
302	  return dueCents(figureCents * periods, latePctOn(sheet, c.date), roundsHalfUp(c.date, sheet));
303	}
304	
305	/** A claim's due in whole cents: the figure fixed when it was settled, else the figure its person's
306	 *  last statement binds it to (none: n/a), else its amount at its grade's rate in force on its date raised to the
307	 *  floor in force on its date (a correction is not), with any late charge added on top of it; null when it has none. Its live
308	 *  figure rounds by `roundsOn`: its date, or for a correction the date of the claim it corrects. */
309	export function claimDueCents(
310	  c: { amount: string; date: string; dueBy: string; status: ClaimStatus; deferredUntil: string | null; settledDue: string | null; stated: boolean; statedDue: string | null },
311	  gradeRates: readonly RateView[],
312	  sheet: DueTerms,
313	  roundsOn: string,
314	): number | null {
315	  if (c.settledDue !== null) return cents(c.settledDue);
316	  let figure: number;
317	  if (c.stated && c.status !== 'PENDING') {
318	    // A statement binds the claim to its figure then, or to none (n/a).
319	    if (c.statedDue === null) return null;
320	    figure = cents(c.statedDue);
321	  } else {
322	    const rate = rateOn(gradeRates, c.date);
323	    if (rate === undefined) return null;
324	    const due = dueCents(cents(c.amount), rate, roundsHalfUp(roundsOn, sheet));
325	    figure = due < 0 ? due : Math.max(due, cents(floorOn(sheet, c.date)));
326	  }
327	  return figure + lateChargeCents(c, figure, sheet);
328	}
