331	// The rates set for each grade on the active sheet, by from-date; a grade with none has no rate.
332	@Injectable({ providedIn: 'root' })
333	export class Rates {
334	  private readonly http = inject(HttpClient);
335	  private readonly sheets = inject(Sheets);
336	  private readonly list = signal<RateView[]>([]);
337	  /** The active sheet's rates of each grade, in the order they take effect. */
338	  readonly ratesByGrade = computed(() => {
339	    const byGrade = new Map<Grade, RateView[]>();
340	    for (const r of [...this.list()].sort(byFrom)) byGrade.set(r.grade, [...(byGrade.get(r.grade) ?? []), r]);
341	    return byGrade;
342	  });
343	  /** The rate of each grade in force on the active sheet's today; a grade with none is missing. */
344	  readonly byGrade = computed(() => {
345	    const today = this.sheets.current()?.today ?? '';
346	    const current = new Map<Grade, string>();
347	    for (const [grade, rates] of this.ratesByGrade()) {
348	      const rate = rateOn(rates, today);
349	      if (rate !== undefined) current.set(grade, rate);
350	    }
351	    return current;
352	  });
