354	  /** Re-read a sheet's rates from the store; null clears them. */
355	  load(sheetId: string | null): Observable<RateView[]> | null {
356	    this.list.set([]);
357	    if (sheetId === null) return null;
358	    return this.http.get<RateView[]>(this.base(sheetId)).pipe(tap((rates) => this.list.set(rates)));
359	  }
