361	  /** Set a grade's rate from a date (null: from the beginning of time) through a to-date (null: it does not end),
362	   *  replacing the one it had from that date. */
363	  set(sheetId: string, grade: Grade, rate: string, from: string | null, to: string | null): Observable<RateView> {
364	    return this.http
365	      .put<RateView>(`${this.base(sheetId)}/${grade}`, { rate, from, to })
366	      .pipe(
367	        tap((saved) =>
