/** A line of a claim's status log: the status it took, the signed-in name of who moved it there, the sheet's
 *  today (yyyy-mm-dd) then, and the due it had at that moment with exactly two decimals (null when it had none). */
export interface ClaimLogLine {
  status: ClaimStatus;
  by: string;
  on: string;
  due: string | null;
}

/** Only OPEN, PENDING and SETTLED claims count toward what is claimed and due. */
export function counts(c: ClaimView): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING' || c.status === 'SETTLED';
}

/** Whether a claim is deferred on the sheet's today: OPEN and deferred until a later day. While deferred it
 *  counts in no total, is not overdue and cannot be settled. */
export function isDeferred(c: Pick<ClaimView, 'deferredUntil' | 'status'>, today: string): boolean {
  return c.status === 'OPEN' && c.deferredUntil !== null && today < c.deferredUntil;
}

/** Whether the claim counts in the live totals on the sheet's today for a person with these holds: a deferred
 *  one does not, nor does an OPEN or PENDING one dated within a hold, unless a statement binds it. */
export function countsWithHolds(holds: readonly HoldView[], today: string): (c: ClaimView) => boolean {
  return (c) =>
    counts(c) &&
    !isDeferred(c, today) &&
    (c.stated ||
      (c.status !== 'OPEN' && c.status !== 'PENDING') ||
      !holds.some((h) => h.from <= c.date && (h.to === null || c.date <= h.to)));
}

/** The date (yyyy-mm-dd) that decides how a claim's live figures round: its own, or for a correction the date
 *  of the claim of the same person it corrects, found among that person's claims. */
export function roundingDate(
  c: Pick<ClaimView, 'date' | 'corrects'>,
  theirs: readonly Pick<ClaimView, 'date' | 'number'>[],
): string {
  if (c.corrects === null) return c.date;
  return theirs.find((o) => o.number === c.corrects)?.date ?? c.date;
}

/** Whether a claim is overdue on the sheet's today: OPEN or PENDING, not deferred, and due by a day before it. */
export function isOverdue(c: Pick<ClaimView, 'dueBy' | 'status' | 'deferredUntil'>, today: string): boolean {
  return (c.status === 'OPEN' || c.status === 'PENDING') && !isDeferred(c, today) && c.dueBy < today;
}

/** A claim as the form submits it: a blank date takes the sheet's today. A negative amount is a correction,
 *  which names in `corrects` the number of the claim it corrects. */
export interface ClaimForm {
  amount: string;
  date: string | null;
  note: string;
  corrects: string | null;
}

/** What a quick-add made: the person the claim is for, whether they were added by it, and the claim. */
export interface QuickAddView {
  person: PersonView;
  personAdded: boolean;
  claim: ClaimView;
}

/** What a paste did: how many claims it added and the claims, in the order added. */
export interface PasteView {
  added: number;
  claims: ClaimView[];
}

/** What a bulk open did: how many it opened and refused, and the claims it opened. */
export interface BulkOpenView {
  opened: number;
  refused: number;
  claims: ClaimView[];
}

/** What a bulk settle did: how many it settled (PENDING ones included) and refused, and the claims it settled. */
export interface BulkSettleView {
  settled: number;
  refused: number;
  claims: ClaimView[];
}

/** An amount the form accepts: 0.00 or more, with up to two decimals. */
export const AMOUNT_PATTERN = /^\d+(\.\d{1,2})?$/;

/** An amount the claim form accepts: AMOUNT_PATTERN, or a negative one (a correction). */
export const CLAIM_AMOUNT_PATTERN = /^-?\d+(\.\d{1,2})?$/;

/** An amount ("12.3", "4", "-0.5") in whole cents, so sums are exact. */
export function cents(amount: string): number {
  const negative = amount.startsWith('-');
  const [whole, frac = ''] = (negative ? amount.slice(1) : amount).split('.');
  const total = Number(whole) * 100 + Number(frac.padEnd(2, '0').slice(0, 2));
  return negative ? -total : total;
}

/** Whole cents as an amount with two decimals, e.g. "-0.30". */
export function money(total: number): string {
  const abs = Math.abs(total);
  return `${total < 0 ? '-' : ''}${Math.trunc(abs / 100)}.${String(abs % 100).padStart(2, '0')}`;
}

// The claims people on a sheet have made, listed newest first.
@Injectable({ providedIn: 'root' })
export class Claims {
  private readonly http = inject(HttpClient);

  list(sheetId: string): Observable<ClaimView[]> {
    return this.http.get<ClaimView[]>(`${this.base(sheetId)}/claims`);
  }

  add(sheetId: string, personId: number, claim: ClaimForm): Observable<ClaimView> {
    return this.http.post<ClaimView>(`${this.base(sheetId)}/people/${personId}/claims`, claim);
  }

  /** Add a DRAFT claim for the person named `name`, dated the sheet's today; one not on the sheet is
   *  added first with grade A. Refused as a whole when the person or the claim is. */
  quickAdd(sheetId: string, name: string, amount: string): Observable<QuickAddView> {
    return this.http.post<QuickAddView>(`${this.base(sheetId)}/quick-add`, { name, amount });
  }

  /** Add a DRAFT claim per line of name,amount,date,note, in order, for people already on the sheet.
   *  Refused as a whole when any line is. */
  paste(sheetId: string, text: string): Observable<PasteView> {
    return this.http.post<PasteView>(`${this.base(sheetId)}/claims/paste`, { text });
  }

  update(sheetId: string, id: number, claim: ClaimForm): Observable<ClaimView> {
    return this.http.put<ClaimView>(`${this.base(sheetId)}/claims/${id}`, claim);
  }

  changeStatus(sheetId: string, id: number, status: ClaimStatus): Observable<ClaimView> {
    return this.http.put<ClaimView>(`${this.base(sheetId)}/claims/${id}/status`, { status });
  }

  /** Defer an OPEN claim until `until` (yyyy-mm-dd), a day after the sheet's today. */
  defer(sheetId: string, id: number, until: string): Observable<ClaimView> {
    return this.http.put<ClaimView>(`${this.base(sheetId)}/claims/${id}/defer`, { until });
  }

  /** A steward approves a PENDING claim: it is SETTLED, its due fixed as it is now. */
  approve(sheetId: string, id: number): Observable<ClaimView> {
    return this.http.put<ClaimView>(`${this.base(sheetId)}/claims/${id}/approve`, {});
  }

  /** A steward re-settles a SETTLED claim: its due fixed again as it would be today as an open, unbound claim. */
  resettle(sheetId: string, id: number): Observable<ClaimView> {
    return this.http.put<ClaimView>(`${this.base(sheetId)}/claims/${id}/resettle`, {});
  }

  /** A steward rejects a PENDING claim with a reason: it is OPEN again. */
  reject(sheetId: string, id: number, reason: string): Observable<ClaimView> {
    return this.http.put<ClaimView>(`${this.base(sheetId)}/claims/${id}/reject`, { reason });
  }

  /** A steward moves a DRAFT, OPEN or PENDING claim to another person: it keeps its number and date, is no
   *  longer bound by a statement, and is listed as that person's newest claim. */
  reassign(sheetId: string, id: number, personId: number): Observable<ClaimView> {
    return this.http.put<ClaimView>(`${this.base(sheetId)}/claims/${id}/person`, { personId });
  }

  /** Open each of the claims that can be opened, numbered in list order; the rest are refused and left as they are. */
  bulkOpen(sheetId: string, ids: readonly number[]): Observable<BulkOpenView> {
    return this.http.post<BulkOpenView>(`${this.base(sheetId)}/claims/bulk-open`, { ids });
  }

  /** Settle each of the claims that can be settled, in list order, as a single settle would; the rest are refused
   *  and left as they are. */
  bulkSettle(sheetId: string, ids: readonly number[]): Observable<BulkSettleView> {
    return this.http.post<BulkSettleView>(`${this.base(sheetId)}/claims/bulk-settle`, { ids });
  }

  private base(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}`;
  }
}

export interface RateView {
  grade: Grade;
  /** The percent with exactly two decimals, e.g. "12.50". */
  rate: string;
  /** The day it takes effect (yyyy-mm-dd); null when it applies from the beginning of time. */
  from: string | null;
  /** The last day it applies (yyyy-mm-dd); null when it does not end. */
  to: string | null;
}

/** The rate among a grade's rates (in the order they take effect) in force on a date (yyyy-mm-dd):
 *  the one with the latest from-date on or before it, unless the date is after its to-date; undefined
 *  when the date is before them all, or that rate has ended by then (an earlier one does not take over again). */
export function rateOn(gradeRates: readonly RateView[], date: string): string | undefined {
  let inForce: RateView | undefined;
  for (const r of gradeRates) if (r.from === null || r.from <= date) inForce = r;
  return inForce === undefined || (inForce.to !== null && inForce.to < date) ? undefined : inForce.rate;
}

/** Rates in the order they take effect: the one with no from-date first, then by from-date. */
function byFrom(a: RateView, b: RateView): number {
  return a.from === b.from ? 0 : a.from === null ? -1 : b.from === null ? 1 : a.from < b.from ? -1 : 1;
}

/** A rate the form accepts: a percent of 0.00 or more, up to 999.99, with up to two decimals. */
export const RATE_PATTERN = /^\d{1,3}(\.\d{1,2})?$/;

/** The floor a sheet starts with. */
export const DEFAULT_FLOOR = '1.00';

/** The due terms used before a sheet is loaded: its starting floor and no late charge. */
export const DEFAULT_DUE_TERMS: DueTerms = { today: '', policyDate: null, settings: [] };

/** The late percent a sheet starts with. */
export const DEFAULT_LATE_PCT = '0.00';

/** What is shown in place of a due when its grade has no rate. */
export const NOT_AVAILABLE = 'n/a';

/** The due on an amount (in whole cents) at a rate (a percent, e.g. "12.50"), in whole cents:
 *  amount × rate / 100, rounded to the cent half to even, or half up when `halfUp` (a negative amount as its
 *  opposite is, negated). Exact, whatever the size of the amount. */
export function dueCents(amountCents: number, rate: string, halfUp = false): number {
  if (amountCents < 0) return -dueCents(-amountCents, rate, halfUp);
  const [whole, frac = ''] = rate.split('.');
  const basisPoints = BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0').slice(0, 2));
  const product = BigInt(amountCents) * basisPoints;
  const quotient = product / 10000n;
  const remainder = product % 10000n;
  const roundUp = remainder > 5000n || (remainder === 5000n && (halfUp || quotient % 2n === 1n));
  return Number(roundUp ? quotient + 1n : quotient);
}

/** The sheet's settings a claim's due depends on: its dated floors and late percents, its policy date and, for
 *  the late charge, its today. */
export type DueTerms = Pick<SheetView, 'today' | 'policyDate' | 'settings'>;

/** The floor in force on a claim's date (yyyy-mm-dd). */
export function floorOn(sheet: DueTerms, date: string): string {
  return settingOn(sheet.settings, 'floor', date, DEFAULT_FLOOR);
}

/** The late percent in force on a claim's date (yyyy-mm-dd). */
export function latePctOn(sheet: DueTerms, date: string): string {
  return settingOn(sheet.settings, 'late-pct', date, DEFAULT_LATE_PCT);
}

/** Whether a claim whose figures round by this date (yyyy-mm-dd) rounds half up: it is before the sheet's policy
 *  date (its today when it has none); on or after it, it rounds half to even. */
export function roundsHalfUp(date: string, sheet: DueTerms): boolean {
  return date < (sheet.policyDate ?? sheet.today);
}

/** The late charge an OPEN or PENDING claim, not deferred, has gained on its figure (in whole cents) by the sheet's today: the
 *  late percent of the figure for every full 30 days past the day it is due by, rounded as the claim rounds.
 *  A correction (a negative amount) gains none. */
export function lateChargeCents(
  c: { amount: string; date: string; dueBy: string; status: ClaimStatus; deferredUntil: string | null },
  figureCents: number,
  sheet: DueTerms,
): number {
  if (cents(c.amount) < 0 || !isOverdue(c, sheet.today)) return 0;
  const days = (Date.parse(sheet.today) - Date.parse(c.dueBy)) / 86_400_000;
  const periods = Math.floor(days / 30);
  if (periods <= 0) return 0;
  return dueCents(figureCents * periods, latePctOn(sheet, c.date), roundsHalfUp(c.date, sheet));
}

/** A claim's due in whole cents: the figure fixed when it was settled, else the figure its person's
 *  last statement binds it to (none: n/a), else its amount at its grade's rate in force on its date raised to the
 *  floor in force on its date (a correction is not), with any late charge added on top of it; null when it has none. Its live
 *  figure rounds by `roundsOn`: its date, or for a correction the date of the claim it corrects. */
export function claimDueCents(
  c: { amount: string; date: string; dueBy: string; status: ClaimStatus; deferredUntil: string | null; settledDue: string | null; stated: boolean; statedDue: string | null },
  gradeRates: readonly RateView[],
  sheet: DueTerms,
  roundsOn: string,
): number | null {
  if (c.settledDue !== null) return cents(c.settledDue);
  let figure: number;
  if (c.stated && c.status !== 'PENDING') {
    // A statement binds the claim to its figure then, or to none (n/a).
    if (c.statedDue === null) return null;
    figure = cents(c.statedDue);
  } else {
    const rate = rateOn(gradeRates, c.date);
    if (rate === undefined) return null;
    const due = dueCents(cents(c.amount), rate, roundsHalfUp(roundsOn, sheet));
    figure = due < 0 ? due : Math.max(due, cents(floorOn(sheet, c.date)));
  }
  return figure + lateChargeCents(c, figure, sheet);
}


// The rates set for each grade on the active sheet, by from-date; a grade with none has no rate.
@Injectable({ providedIn: 'root' })
export class Rates {
  private readonly http = inject(HttpClient);
  private readonly sheets = inject(Sheets);
  private readonly list = signal<RateView[]>([]);
  /** The active sheet's rates of each grade, in the order they take effect. */
  readonly ratesByGrade = computed(() => {
    const byGrade = new Map<Grade, RateView[]>();
    for (const r of [...this.list()].sort(byFrom)) byGrade.set(r.grade, [...(byGrade.get(r.grade) ?? []), r]);
    return byGrade;
  });
  /** The rate of each grade in force on the active sheet's today; a grade with none is missing. */
  readonly byGrade = computed(() => {
    const today = this.sheets.current()?.today ?? '';
    const current = new Map<Grade, string>();
    for (const [grade, rates] of this.ratesByGrade()) {
      const rate = rateOn(rates, today);
      if (rate !== undefined) current.set(grade, rate);
    }
    return current;
  });

  /** Re-read a sheet's rates from the store; null clears them. */
  load(sheetId: string | null): Observable<RateView[]> | null {
    this.list.set([]);
    if (sheetId === null) return null;
    return this.http.get<RateView[]>(this.base(sheetId)).pipe(tap((rates) => this.list.set(rates)));
  }

  /** Set a grade's rate from a date (null: from the beginning of time) through a to-date (null: it does not end),
   *  replacing the one it had from that date. */
  set(sheetId: string, grade: Grade, rate: string, from: string | null, to: string | null): Observable<RateView> {
    return this.http
      .put<RateView>(`${this.base(sheetId)}/${grade}`, { rate, from, to })
      .pipe(
        tap((saved) =>
          this.list.update((list) => [...list.filter((r) => r.grade !== saved.grade || r.from !== saved.from), saved]),
        ),
      );
  }

  private base(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/rates`;
  }
}

export type Grade = 'A' | 'B' | 'C';
export const GRADES: readonly Grade[] = ['A', 'B', 'C'];

/** A grade recorded for a person, in force from its from-date (yyyy-mm-dd) until the next one's; the
 *  first grade a person was given has none: it applies from the beginning of time. */
export interface GradeFrom {
  grade: Grade;
  from: string | null;
}

/** A hold on a person from its from-date to its to-date (yyyy-mm-dd), both inclusive; a null to-date has no end. */
export interface HoldView {
  from: string;
  to: string | null;
}

export interface PersonView {
  id: number;
  name: string;
  /** The grade in force on the sheet's today when the person was read. */
  grade: Grade;
  /** Every grade recorded, in the order they take effect. */
  grades: GradeFrom[];
  /** Raised on every save; an edit names the version it was made from. */
  version: number;
  /** Retired as soon as a retirement date is set, whatever the date. */
  retired: boolean;
  /** The date the person is retired from (yyyy-mm-dd); null while not retired. */
  retiredFrom: string | null;
  /** Whether the person has any hold, whatever its dates. */
  held: boolean;
  /** The person's holds, in the order they start: their open claims dated within one, and not bound by a
   *  statement, count in no live total. */
  holds: HoldView[];
}

export interface PersonForm {
  name: string;
  grade: Grade;
}

/** An edit of a person: the grade is recorded from `gradeFrom` (yyyy-mm-dd; null takes the sheet's today). */
export interface PersonEdit extends PersonForm {
  gradeFrom: string | null;
}

/** The person's grade in force on `date` (yyyy-mm-dd): the one with the latest from-date on or before it. */
export function gradeOn(p: Pick<PersonView, 'grade' | 'grades'>, date: string): Grade {
  let inForce: GradeFrom | undefined;
  for (const g of p.grades) {
    if ((g.from === null || g.from <= date) && (inForce === undefined || (inForce.from ?? '') <= (g.from ?? ''))) inForce = g;
  }
  return inForce?.grade ?? p.grade;
}

// The people kept on a sheet, listed in the order they were added.
@Injectable({ providedIn: 'root' })
export class People {
  private readonly http = inject(HttpClient);
  /** Whether retired people are listed: belongs to the screen, so loading a sheet leaves it as it is. */
  readonly showRetired = signal(false);

  list(sheetId: string): Observable<PersonView[]> {
    return this.http.get<PersonView[]>(this.base(sheetId));
  }

  add(sheetId: string, person: PersonForm): Observable<PersonView> {
    return this.http.post<PersonView>(this.base(sheetId), person);
  }

  /** Save an edit made from `version` of the person; refused (412) when someone has saved them since. */
  update(sheetId: string, id: number, version: number, person: PersonEdit): Observable<PersonView> {
    return this.http.put<PersonView>(`${this.base(sheetId)}/${id}`, { ...person, version });
  }

  /** Retire the person from `from` (yyyy-mm-dd); null takes the sheet's today. */
  retire(sheetId: string, id: number, from: string | null): Observable<PersonView> {
    return this.http.post<PersonView>(`${this.base(sheetId)}/${id}/retire`, { from });
  }

  /** Put the person on hold from `from` (null takes the sheet's today) to `to` (null: no end). */
  hold(sheetId: string, id: number, from: string | null, to: string | null): Observable<PersonView> {
    return this.http.post<PersonView>(`${this.base(sheetId)}/${id}/hold`, { from, to });
  }

  private base(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/people`;
  }
}

export interface PeriodView {
  id: number;
  /** Unique on its sheet. */
  name: string;
  /** The first day of the period (yyyy-mm-dd), inclusive. */
  from: string;
  /** The last day of the period (yyyy-mm-dd), inclusive. */
  to: string;
  /** Whether the period is closed: no claim dated inside it can be added, edited or moved. */
  closed: boolean;
  /** The due-total fixed when the period was closed, with exactly two decimals; null while open. */
  closedTotal: string | null;
  /** Each person's due-total for the period, by person id, fixed when it was closed; empty while open. A person
   *  missing (added later) has 0.00. */
  closedPersonTotals: Record<string, string>;
}

/** A period as the form submits it: a blank from-date takes the sheet's today. */
export interface PeriodForm {
  name: string;
  from: string | null;
  to: string;
}

/** The period whose dates contain a date (yyyy-mm-dd); undefined when none does. */
export function periodOn(periods: readonly PeriodView[], date: string): PeriodView | undefined {
  return periods.find((p) => p.from <= date && date <= p.to);
}

// The periods of the active sheet, by from-date; no two of them overlap.
@Injectable({ providedIn: 'root' })
export class Periods {
  private readonly http = inject(HttpClient);
  private readonly periods = signal<PeriodView[]>([]);
  readonly list = this.periods.asReadonly();

  /** Re-read a sheet's periods from the store; null clears them. */
  load(sheetId: string | null): Observable<PeriodView[]> | null {
    this.periods.set([]);
    if (sheetId === null) return null;
    return this.http.get<PeriodView[]>(this.base(sheetId)).pipe(tap((periods) => this.periods.set(periods)));
  }

  /** Add a period; refused when its name is in use, it ends before it starts, or it overlaps another. */
  add(sheetId: string, period: PeriodForm): Observable<PeriodView> {
    return this.http
      .post<PeriodView>(this.base(sheetId), period)
      .pipe(tap((saved) => this.periods.update((list) => [...list, saved].sort((a, b) => (a.from < b.from ? -1 : 1)))));
  }

  /** Close a period, fixing its due-total; refused when it is already closed. */
  close(sheetId: string, name: string): Observable<PeriodView> {
    return this.http
      .post<PeriodView>(`${this.base(sheetId)}/${encodeURIComponent(name)}/close`, {})
      .pipe(tap((saved) => this.periods.update((list) => list.map((p) => (p.id === saved.id ? saved : p)))));
  }

  /** Reopen a closed period, making its due-total live again; only a steward may. */
  reopen(sheetId: string, name: string): Observable<PeriodView> {
    return this.http
      .post<PeriodView>(`${this.base(sheetId)}/${encodeURIComponent(name)}/reopen`, {})
      .pipe(tap((saved) => this.periods.update((list) => list.map((p) => (p.id === saved.id ? saved : p)))));
  }

  private base(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/periods`;
  }
}

/** A dated setting's value from its from-date (yyyy-mm-dd; null: from the beginning of time) until the next one's
 *  of the same key; a null value means none. Keys: clerk-limit, floor, terms, terms-A/B/C, late-pct, cap. */
export interface DatedSetting {
  key: string;
  from: string | null;
  value: string | null;
}

/** The sheet as the screen shows it: each dated setting as it is in force on its today. */
export interface SheetView {
  id: string;
  /** The sheet's today (yyyy-mm-dd): every date-dependent decision and default uses it, never the clock. */
  today: string;
  /** A clerk can settle a claim only when its due is at or below this (two decimals); null: no limit. */
  clerkLimit: string | null;
  /** A claim's live due is at least this (two decimals). */
  floor: string;
  /** The sheet's terms in days: a claim is due by its date plus these. */
  terms: number;
  /** The sheet's late percent (two decimals): an overdue claim's due gains this percent of its figure
   *  for every full 30 days it is overdue. */
  latePct: string;
  /** The sheet's policy date (yyyy-mm-dd): a claim dated before it rounds half up, one on or after it half to
   *  even; null when it is the sheet's today. */
  policyDate: string | null;
  /** The sheet's period numbering from (yyyy-mm-dd): while its today is on or after it, a claim opened is
   *  numbered within its period; null when off. */
  periodNumberingFrom: string | null;
  /** The terms in days set per grade; a grade without its own uses the sheet's terms. */
  gradeTerms: Partial<Record<Grade, number>>;
  /** A person's due-total is at most this (two decimals); null: none. */
  cap: string | null;
  /** Every dated value recorded for the settings that carry a figure. */
  settings: DatedSetting[];
}

/** A setting's value in force on a date (yyyy-mm-dd): the one recorded with the latest from-date on or before it;
 *  `start` (the sheet's starting value) before every from-date, or when it is none. */
export function settingOn(settings: readonly DatedSetting[], key: string, date: string, start: string): string {
  let inForce: DatedSetting | undefined;
  for (const s of settings) {
    if (s.key === key && (s.from === null || s.from <= date) && (inForce === undefined || inForce.from === null
        || (s.from !== null && s.from > inForce.from))) inForce = s;
  }
  return inForce?.value ?? start;
}

/** The terms a sheet has until they are changed. */
export const DEFAULT_TERMS = 14;

// The active sheet. Everything else in the app is kept per sheet; loading an id re-reads it from
// the store, and an id never loaded before starts an empty sheet.
@Injectable({ providedIn: 'root' })
export class Sheets {
  private readonly http = inject(HttpClient);
  private readonly active = signal<SheetView | null>(null);
  readonly current = this.active.asReadonly();
  /** The sheet as last (re)loaded: set on each load only, so changing its today re-reads nothing. */
  private readonly lastLoad = signal<SheetView | null>(null);
  readonly loaded = this.lastLoad.asReadonly();

  load(id: string): Observable<SheetView> {
    return this.http
      .post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/load`, null)
      .pipe(
        tap((s) => {
          this.active.set(s);
          this.lastLoad.set(s);
        }),
      );
  }

  /** Change the active sheet's today. */
  setToday(id: string, today: string): Observable<SheetView> {
    return this.http
      .put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/today`, { today })
      .pipe(tap((s) => this.active.set(s)));
  }

  /** Record the active sheet's clerk limit from a date (null: its today); a null clerk limit means no limit. */
  setSettings(id: string, clerkLimit: string | null, from: string | null): Observable<SheetView> {
    return this.http
      .put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/settings`, { clerkLimit, from })
      .pipe(tap((s) => this.active.set(s)));
  }

  /** Record the active sheet's floor from a date (null: its today). */
  setFloor(id: string, floor: string, from: string | null): Observable<SheetView> {
    return this.http
      .put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/settings/floor`, { floor, from })
      .pipe(tap((s) => this.active.set(s)));
  }

  /** Record the active sheet's terms (days) from a date (null: its today). */
  setTerms(id: string, terms: number, from: string | null): Observable<SheetView> {
    return this.http
      .put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/settings/terms`, { terms, from })
      .pipe(tap((s) => this.active.set(s)));
  }

  /** Record a grade's own terms (days) from a date (null: the sheet's today); null leaves the grade on the sheet's terms. */
  setGradeTerms(id: string, grade: Grade, terms: number | null, from: string | null): Observable<SheetView> {
    return this.http
      .put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/settings/terms/${grade}`, { terms, from })
      .pipe(tap((s) => this.active.set(s)));
  }

  /** Change the active sheet's policy date; null means the sheet's today. */
  setPolicyDate(id: string, policyDate: string | null): Observable<SheetView> {
    return this.http
      .put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/settings/policy-date`, { policyDate })
      .pipe(tap((s) => this.active.set(s)));
  }

  /** Change the active sheet's period numbering from; null means off. */
  setPeriodNumberingFrom(id: string, periodNumberingFrom: string | null): Observable<SheetView> {
    return this.http
      .put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/settings/period-numbering-from`, { periodNumberingFrom })
      .pipe(tap((s) => this.active.set(s)));
  }

  /** Record the active sheet's late percent from a date (null: its today). */
  setLatePct(id: string, latePct: string, from: string | null): Observable<SheetView> {
    return this.http
      .put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/settings/late-pct`, { latePct, from })
      .pipe(tap((s) => this.active.set(s)));
  }

  /** Record the active sheet's cap from a date (null: its today); null means none. */
  setCap(id: string, cap: string | null, from: string | null): Observable<SheetView> {
    return this.http
      .put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/settings/cap`, { cap, from })
      .pipe(tap((s) => this.active.set(s)));
  }
}
